// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {PredictTheBlockHashChallenge} from "../src/PredictTheBlockHashChallenge.sol";

contract InvMutTest is Test {
    PredictTheBlockHashChallenge c;
    function setUp() public { c = new PredictTheBlockHashChallenge{value: 1 ether}(); }

    function testFuzz_property(uint256 n, address actor) public {
        vm.assume(actor != address(0) && actor != address(c));
        n = bound(n, 2, 1_000_000_000);

        // Peek the deterministic blockhash of block n, then rewind to lock it in.
        vm.roll(n + 1);
        bytes32 bh = blockhash(n);
        vm.assume(bh != keccak256(abi.encodePacked(bh))); // keccak has no known fixed point

        // Lock in the RAW blockhash of the target block as the guess (target = n).
        vm.roll(n - 1);
        vm.deal(actor, 1 ether);
        vm.prank(actor);
        c.lockInGuess{value: 1 ether}(bh);

        // Settle one block past the target.
        vm.roll(n + 1);
        vm.prank(actor);
        c.settle();

        // Rule: a guess equal to the raw blockhash never wins, because the answer
        // is keccak256(blockhash(n)) — the contract must still hold its 2 ether.
        assertTrue(address(c).balance == 2 ether);
    }
}
